struct TrieNode {
    children: [Option<Box<TrieNode>>; 26],
    is_word: bool,
}

impl TrieNode {
    fn new() -> Self {
        TrieNode {
            children: Default::default(),
            is_word: false,
        }
    }
}

struct WordDictionary {
    root: TrieNode,
}

impl WordDictionary {
    pub fn new() -> Self {
        WordDictionary {
            root: TrieNode::new(),
        }
    }

    pub fn add_word(&mut self, word: String) {
        let mut curr = &mut self.root;
        for c in word.chars() {
            let idx = (c as u8 - b'a') as usize;
            if curr.children[idx].is_none() {
                curr.children[idx] = Some(Box::new(TrieNode::new()));
            }
            curr = curr.children[idx].as_mut().unwrap();
        }
        curr.is_word = true;
    }

    pub fn search(&self, word: String) -> bool {
        Self::dfs(&word, 0, &self.root)
    }

    fn dfs(word: &str, j: usize, node: &TrieNode) -> bool {
        let chars: Vec<char> = word.chars().collect();
        let mut curr = node;

        for i in j..chars.len() {
            let c = chars[i];
            if c == '.' {
                for child in curr.children.iter() {
                    if let Some(child_node) = child {
                        if Self::dfs(word, i + 1, child_node) {
                            return true;
                        }
                    }
                }
                return false;
            } else {
                let idx = (c as u8 - b'a') as usize;
                match &curr.children[idx] {
                    Some(child_node) => curr = child_node,
                    None => return false,
                }
            }
        }
        curr.is_word
    }
}

